CREATE TRIGGER trace_cases_insert AFTER INSERT ON cases
BEGIN
 SELECT RAISE(ABORT,'Missing mutation context') WHERE NOT EXISTS(SELECT 1 FROM mutation_context WHERE owner=NEW.owner AND expires_at>CAST(strftime('%s','now') AS INTEGER)*1000);
 INSERT INTO change_journal(owner,request_id,actor,actor_name,entity,entity_id,case_id,operation,reason,before_data,after_data,created_at)
 SELECT NEW.owner,token,actor,actor_name,'cases',NEW.id,NEW.id,'INSERT',reason,NULL,json_set(NEW.data,'$.reference',NEW.reference),strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM mutation_context WHERE owner=NEW.owner;
END;
