CREATE TRIGGER bump_case_data AFTER UPDATE OF data ON cases WHEN OLD.data IS NOT NEW.data BEGIN UPDATE cases SET revision=revision+1 WHERE id=NEW.id; END;
CREATE TRIGGER bump_documents_insert AFTER INSERT ON documents BEGIN UPDATE cases SET revision=revision+1 WHERE id=NEW.case_id; END;
